mapper.select:
SELECT *
FROM xsy_order_operation_log
WHERE TRUE

    AND (order_id IN (SELECT so.id FROM xsy_sales_order so WHERE so.deleted = FALSE AND so.seller_id IN
    #{scopeId}
    ) OR customer_id IN (SELECT c.id FROM xsy_customer c WHERE c.deleted = FALSE AND c.seller_id IN
    #{scopeId}
    ))

AND FALSE

    AND operation_type = #{query.operationType}



    AND (order_id IN (SELECT so.id FROM xsy_sales_order so WHERE so.deleted = FALSE
    AND (so.order_no ILIKE '%' || #{query.keyword} || '%'
    OR so.customer_name_snapshot ILIKE '%' || #{query.keyword} || '%'))
    OR customer_id IN (SELECT c.id FROM xsy_customer c WHERE c.deleted = FALSE
    AND c.name ILIKE '%' || #{query.keyword} || '%'))

AND order_id = #{query.orderId}
AND created_at >= #{query.startTime}
AND created_at < #{query.endTime}
ORDER BY created_at DESC, id DESC
